/**
 * Ship the LLM docs in the npm package: AGENTS.md at the package root and the compact component cards in llms/cards,
 * so coding agents read the docs of the installed version from node_modules without any setup.
 *
 * The cards are generated by the docs app (build:llm-docs); run this after it, before publishing.
 */
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { renderAgentsMd } from '../../../apps/docs/scripts/llm/agents.mjs';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const PACKAGE_DIR = path.resolve(__dirname, '..');
const OUTPUT_DIR = path.join(PACKAGE_DIR, process.env.OUTPUT_DIR || 'dist');
const CARDS_DIR = path.resolve(__dirname, '../../../apps/docs/public/llms/cards');
const SITE_URL = 'https://exhaustive-ui.com';

if (!fs.existsSync(path.join(CARDS_DIR, 'index.json'))) {
    console.error(`No component cards in ${CARDS_DIR}: run \`pnpm --filter docs build:docs\` (or build:llm-docs) first.`);
    process.exit(1);
}

if (!fs.existsSync(path.join(OUTPUT_DIR, 'package.json'))) {
    console.error(`${OUTPUT_DIR} is not a built package: run \`pnpm --filter @exhaustive-ui/core build\` first.`);
    process.exit(1);
}

const cards = JSON.parse(fs.readFileSync(path.join(CARDS_DIR, 'index.json'), 'utf-8'));
const { version } = JSON.parse(fs.readFileSync(path.join(PACKAGE_DIR, 'package.json'), 'utf-8'));
const target = path.join(OUTPUT_DIR, 'llms', 'cards');

fs.rmSync(path.join(OUTPUT_DIR, 'llms'), { recursive: true, force: true });
fs.mkdirSync(target, { recursive: true });
for (const card of cards) fs.copyFileSync(path.join(CARDS_DIR, `${card.name}.md`), path.join(target, `${card.name}.md`));
fs.writeFileSync(path.join(OUTPUT_DIR, 'AGENTS.md'), renderAgentsMd({ version, cards, cardLink: (name) => `llms/cards/${name}.md`, docsLink: (route) => `${SITE_URL}/${route}` }), 'utf-8');

console.log(`✓ AGENTS.md and ${cards.length} component cards added to ${path.relative(process.cwd(), OUTPUT_DIR) || '.'}`);
